import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();

        StringBuilder sb = new StringBuilder();

        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= n; j++) {
                int value = Math.min(
                    Math.min(i, n - i + 1),
                    Math.min(j, n - j + 1)
                );

                if (j > 1) {
                    sb.append(' ');
                }
                sb.append(value);
            }
            sb.append('\n');
        }

        System.out.print(sb);
    }
}
